import '../../features/privacy/domain/privacy_checklist.dart';
import 'portuguese_portugal_text.dart';

/// Brazilian Portuguese privacy self-audit guidance.
class PortuguesePrivacyContent {
  PortuguesePrivacyContent._();

  static const Map<String, Map<String, String>> _practices = {
    'account-unique-passwords': {'title':'Use senhas exclusivas nas contas importantes','why':'Reutilizar uma senha significa que um vazamento em um serviço também pode colocar suas outras contas em risco.','action':'Use um gerenciador de senhas confiável para criar uma senha longa e diferente para cada conta importante. Proteja o gerenciador com uma senha mestra forte e configure as opções de recuperação disponíveis.','limit':'Um gerenciador de senhas não protege a conta se a senha mestra ou o canal de recuperação for comprometido.'},
    'account-mfa': {'title':'Ative a autenticação multifator','why':'Um segundo fator pode reduzir o impacto do roubo de uma senha.','action':'Ative MFA nas contas de e-mail, financeiras, de nuvem e redes sociais. Quando possível, prefira chaves de acesso ou chaves de segurança e proteja os backups do aplicativo autenticador.','limit':'Os métodos de MFA têm níveis de segurança diferentes. Códigos SMS podem ficar expostos a ataques de troca de SIM ou portabilidade fraudulenta.'},
    'account-recovery': {'title':'Revise as opções de recuperação das contas','why':'Um e-mail ou telefone de recuperação desatualizado pode impedir uma recuperação legítima ou facilitar a tomada da conta.','action':'Confira endereços de recuperação, números de telefone, códigos de backup e dispositivos confiáveis nas configurações oficiais de segurança de cada serviço.','limit':'As configurações de recuperação variam por serviço. O ORVIKA não consegue verificar se o provedor aplicou as alterações.'},
    'device-updates': {'title':'Mantenha sistemas e aplicativos atualizados','why':'Atualizações frequentemente corrigem vulnerabilidades que poderiam ser exploradas por invasores.','action':'Ative atualizações automáticas de segurança quando possível. Instale atualizações pelo atualizador integrado do dispositivo ou pela loja oficial.','limit':'Uma atualização reduz riscos conhecidos, mas não garante que o dispositivo esteja livre de comprometimento.'},
    'device-lock': {'title':'Proteja o dispositivo com um bloqueio de tela forte','why':'Um dispositivo perdido ou deixado desbloqueado pode expor mensagens, contas e dados armazenados.','action':'Use um PIN ou senha longa, defina um intervalo curto para bloqueio automático e configure a biometria como método adicional e prático de desbloqueio.','limit':'As opções biométricas e de bloqueio variam conforme o dispositivo. O bloqueio de tela não criptografa necessariamente todos os backups externos.'},
    'device-backups': {'title':'Confira os backups e as opções de localização do dispositivo','why':'Backups facilitam a recuperação, enquanto recursos de localização podem ajudar a encontrar ou proteger remotamente um dispositivo perdido.','action':'Confira quais dados são copiados, quem pode acessar a conta de backup, se há criptografia disponível e se a localização e o bloqueio remoto estão ativados.','limit':'A disponibilidade e os padrões de criptografia variam conforme o sistema operacional e o provedor. Consulte a documentação atual do provedor.'},
    'apps-permissions': {'title':'Revise as permissões dos aplicativos','why':'Aplicativos podem manter acesso à localização, contatos, câmera, microfone, fotos ou dispositivos próximos além do necessário.','action':'Abra as configurações de privacidade ou permissões de aplicativos do sistema. Remova acessos desnecessários e, quando disponível, prefira acesso único ou apenas durante o uso.','limit':'Os nomes e controles de permissões variam conforme o sistema e a versão. O ORVIKA não lê nem altera essas permissões.'},
    'apps-unused': {'title':'Remova aplicativos que você não usa mais','why':'Aplicativos sem uso podem manter sessões abertas, armazenar dados ou continuar recebendo atualizações e permissões.','action':'Desinstale aplicativos desnecessários. Antes de removê-los, exporte as informações de que precisa e, quando apropriado, revogue o acesso às contas conectadas.','limit':'Desinstalar um aplicativo não necessariamente apaga os dados que o provedor já mantém.'},
    'apps-sources': {'title':'Instale aplicativos de fontes confiáveis','why':'Instaladores não verificados e aplicativos modificados podem conter código indesejado ou solicitar acesso excessivo.','action':'Use lojas oficiais ou o canal de distribuição verificado do desenvolvedor. Antes de instalar, confira o desenvolvedor, as permissões solicitadas e o histórico de atualizações.','limit':'Estar em uma loja oficial não garante que um aplicativo seja seguro ou respeite a privacidade.'},
    'browsing-tracking': {'title':'Revise os controles de privacidade e rastreamento do navegador','why':'Cookies, permissões de sites e rastreamento entre sites podem revelar hábitos de navegação.','action':'Revise a proteção contra rastreamento, os controles de cookies de terceiros, as permissões de sites salvas e as extensões. Remova extensões que não reconhece ou não precisa.','limit':'Bloquear rastreadores pode afetar o funcionamento de sites e não torna a navegação anônima.'},
    'browsing-sharing': {'title':'Limite as informações pessoais compartilhadas publicamente','why':'Publicações públicas e detalhes do perfil podem ser combinados para facilitar falsidade ideológica, golpes direcionados ou ataques à recuperação de contas.','action':'Revise campos públicos do perfil, configurações de público, compartilhamento de localização e publicações antigas. Evite publicar documentos de identidade, planos de viagem ou pistas de recuperação de conta.','limit':'O conteúdo pode ser copiado ou arquivado antes que você altere as configurações de privacidade.'},
    'browsing-network': {'title':'Use conexões confiáveis e confira solicitações de rede','why':'Portais Wi-Fi falsos e conexões desprotegidas podem expor sua atividade ou redirecioná-lo para páginas enganosas.','action':'Prefira redes confiáveis, confirme o nome da rede com o responsável, evite operações sensíveis em redes desconhecidas e use sites HTTPS. Desative a conexão automática a pontos de acesso desconhecidos.','limit':'HTTPS protege os dados durante o tráfego até o site, mas não comprova que ele seja legítimo nem torna confiável uma rede desconhecida.'},
  };

  static PrivacyPractice localize(PrivacyPractice practice, String languageCode) {
    if (languageCode != 'pt' && languageCode != 'pt-PT') return practice;
    final values = _practices[practice.id];
    if (values == null) return practice;
    return PrivacyPractice(id: practice.id, title: languageCode == 'pt-PT' ? PortuguesePortugalText.adapt(values['title']!) : values['title']!, category: practice.category,
      why: languageCode == 'pt-PT' ? PortuguesePortugalText.adapt(values['why']!) : values['why']!, action: languageCode == 'pt-PT' ? PortuguesePortugalText.adapt(values['action']!) : values['action']!, limit: languageCode == 'pt-PT' ? PortuguesePortugalText.adapt(values['limit']!) : values['limit']!);
  }
}
